strings:

; ---- Subroutine: strings.length ----
    ALIGN 2

strings.length:
            moveq    #0,d0
            bra.s    .enter
.loop:
            addq.w   #1,d0
.enter:
            tst.b    (a0)+
            bne      .loop
            rts
; End of subroutine: strings.length


; ---- Subroutine: strings.compare ----
    ALIGN 2

strings.compare:
            jmp  prog8_lib.strcmp
; End of subroutine: strings.compare


; ---- Subroutine: strings.hash ----
    ALIGN 2

strings.hash:
            movea.l  d0,a0
            move.b   #179,d0
            moveq    #0,d1
            move.w   d1,ccr          ; clear flags (X=0 for roxl)
            bra      .enter
.loop:
            roxl.b   #1,d0
            eor.b    d1,d0
.enter:
            move.b   (a0)+,d1
            bne      .loop
            rts
; End of subroutine: strings.hash


; ---- Subroutine: strings.copy ----
    ALIGN 2

strings.copy:
            movea.l  d0,a0
            movea.l  d1,a1
            moveq    #0,d0
.loop:
            move.b   (a0)+,d2
            move.b   d2,(a1)+
            beq      .done
            addq.l   #1,d0
            bra.s    .loop
.done:
            rts
; End of subroutine: strings.copy


; ---- Subroutine: strings.ncopy ----
    ALIGN 2

strings.ncopy:
            movea.l  d0,a0
            movea.l  d1,a1
            moveq    #0,d0
            tst.b    d2
